  "{0} has a battery crew waiting for the Portuguese patterns and proof pieces. {1} refits will remain after this one.": "{0} には砲兵隊がポルトガルのパターンと証拠品を待っています。 {1} の改修はこの後も残ります。",
  "{0} has already been stripped of portable wealth. The battered harbor remains under arms until its defenses recover.": "{0} はすでにポータブルな富を剥奪されています。荒廃した港は、防御が回復するまで武器の下に置かれます。",
  "{0} has been plundered. Your raiders carry off {1} doubloons, but the city remains under its former flag.": "{0} が略奪されました。襲撃者たちは {1} 個のダブロンを持ち去りましたが、都市は以前の旗のままです。",
  "{0} has chosen negotiation before war. Carry me to {1} with articles concerning tribute and allegiance, then return for {2} db.": "{0} は戦前の交渉を選択しました。貢物と忠誠に関する記事を持って {1} に連れて行ってから、{2} DB に戻ります。",
  "{0} has drawn grave notice in Rome. Carry the Pope's sealed admonition": "{0} はローマで重大な注意を呼び起こしました。教皇の封印された戒めを伝える",
