  "{0} has fallen. The commissioners brought its court to terms, and the": "{0} は下落しました。委員たちは裁判所に和解をもたらし、",
  "{0} has fallen. The commissioners brought its court to terms, and the princes and envoys sealed peace. The treasury will honor": "{0} は下落しました。委員たちは法廷を和解させ、王子と使者は和平を締結した。財務省は尊重するだろう",
  "{0} has fallen. The commissioners brought its court to terms, and the princes and envoys sealed peace. The treasury will honor {1}'s extraordinary commission.": "{0} は下落しました。委員たちは法廷を和解させ、王子と使者は和平を締結した。財務省は {1} の特別な任務を尊重します。",
  "{0} has forbidden {1} from {2}": "{0} は {1} による {2} を禁止しました",
  "{0} has lost its last port, but loyal servants have not abandoned the flag. This expedition can keep our cause alive overseas until fortune turns.": "{0} は最後の港を失いましたが、忠実な家臣たちは旗を捨てませんでした。この遠征により、運命が変わるまで海外で私たちの大義を存続させることができます。",
  "{0} has reached {1}.": "{0} が {1} に達しました。",
