  "{0} has received the court's receipt. The treasury will pay {1} db.": "{0} は裁判所の受領書を受け取りました。財務省は {1} DB に支払います。",
  "{0} has sealed instructions for the election of a {1}. Carry me to {2} and home for {3} db. My prince alone chooses; your duty is only our passage.": "{0} には、{1} の選出に関する指示が封印されています。 {2} まで運んで、{3} DB のために家に帰ります。私の王子様だけが選択します。あなたの義務は私たちの通過点にすぎません。",
  "{0} has submitted to the commissioners and the rulers have sealed peace. Carry the final dispatches to {1}.": "{0} は委員会に服従し、支配者たちは和平を締結しました。最後のディスパッチを {1} に運びます。",
  "{0} has surrendered. The captured treasury yields {1} doubloons.{2}{3}": "{0} は降伏しました。占領された国庫からは {1} ダブロンが得られます。{2}{3}",
