  "colonists, sailors, and the first planting season": "入植者、船員、そして最初の植栽の季節",
  "Colony secure. +{0} db.": "入植地は安全。+{0} DB。",
  "Colossal stone ancestors stand watch over Rapa Nui. How did one island raise so many?": "巨大な石の先祖がラパヌイを見守っています。一つの島がどのようにしてこれほど多くの個体を育てたのでしょうか？",
