  "Composite Recurve Bows": "コンポジットリカーブボウ",
  "Concepcion endures at Penco as a military and administrative center, sustained from Peru on a frontier Spain has not subdued.": "コンセプシオンは、スペインが征服していない辺境のペルーから維持され、軍事および行政の中心地としてペンコに存続している。",
