  "CONTROLLED SPICES SURRENDERED {0}": "管理されたスパイスを放棄しました {0}",
  "Cooperation as a weapon. That is a finer observation than any measurement of tooth or paw, and one our moralizing bestiaries would likely misunderstand.": "協力を武器に。これは、歯や足のどんな測定よりも優れた観察であり、道徳的な動物寓話家が誤解する可能性のあるものです。",
  "Costly self-igniting pistols are deadly at close range and useful in a landing party.": "高価な自己発火式ピストルは近距離では致命的であり、上陸部隊では役に立ちます。",
  "COSTS": "費用",
  "Cotton and tobacco occupy the promoters, but neither feeds a hungry harbor town.": "綿花とタバコが推進者となっているが、どちらも飢えた港町を養うものではない。",
  "COULD NOT END CURRENT VOYAGE": "現在の航海を終了できませんでした",
  "Council": "評議会",
  "Council {0}": "評議会{0}",
  "Court can have it. I need you fit for the next watch.": "裁判所はそれを行うことができます。次の試合に向けて体調を整えてもらいたい。",
  "court dialogue destination": "法廷での対話の目的地",
  "court dialogue origin": "法廷対話の起源",
  "Court notice: {0} is gone. {1} now rules {2}.": "裁判所からの通知: {0} は失踪しました。 {1} が {2} を支配するようになりました。",
  "COVER": "表紙",
  "craft worker": "職人",
  "Cranes swing over the crowded wharf while guild clerks tally barrels, bales, and ships waiting on the tide.": "ギルドの事務員が樽、俵、潮の満ち引きを待つ船の数を数えている間、クレーンが混雑した埠頭の上で揺れます。",
  "cranes, locks, hoops, and sugar-mill repairs": "クレーン、ロック、フープ、製糖工場の修理",
  "Create a domestic matchlock industry in Japan.": "日本に国産火縄銃産業を創る。",
  "Creation and destruction from one furnace. Mark the fresh flows separately from the cultivated slopes; the island's prosperity and danger share a source.": "一つの炉から創造と破壊。耕作された斜面とは別に、新鮮な流れをマークします。島の繁栄と危険の源は共通している。",
  "Crew": "乗組員",
