  "Cross-staff, compass, tables. With all these instruments, surely one can tell us where breakfast went.": "クロススタッフ、コンパス、テーブル。これらすべての器具があれば、きっと朝食がどこに行ったかを知ることができるでしょう。",
  "Crossbows": "クロスボウ",
  "CROWN {0}{1}%": "クラウン {0}{1}%",
