  "CROWN FALLEN: THE WAR LOAN CANNOT BE PAID": "王権崩壊：戦費借款は返済不能",
  "Crowns change hands: {0} now rules {1} after {2}.": "王冠の所有者が変わります: {0} は、{2} の後に {1} を支配します。",
  "Crunch. Crunch.": "クランチ。クランチ。",
  "curing cod for the voyage back across the Atlantic": "大西洋を横断して戻る航海のためにタラを塩漬けにする",
  "curing fish and preserving provisions for port laborers": "魚の塩漬けと港湾労働者のための食糧の保存",
  "Current battery: {0}. Faster locks and longer culverins improve reload, damage, and range. Purse {1} db.": "現在のバッテリー: {0}。より速いロックとより長いカルバリンにより、リロード、ダメージ、射程が向上します。財布 {1} DB。",
  "Current gear: {0}. Other nets offered: {1}. Purse {2} db.": "現在のギア: {0}。提供されている他のネット: {1}。財布 {2} DB。",
  "Current harpoon: {0}. A stronger line and truer shaft improve the odds of holding a surfaced whale. Purse {1} db.": "現在の銛: {0}。より強力なラインとより忠実なシャフトにより、浮上したクジラを捕まえる確率が向上します。財布 {1} DB。",
  "CURRENT SHIP WILL BE REPLACED": "現在の船は置き換えられます",
  "Cusabo food and support have kept the settlement alive, but the Proprietors' own crops have disappointed them.": "クサボの食糧と支援によって入植地は存続してきたが、所有者自身の作物は彼らを失望させた。",
