  "Denali rises from low country with scarcely any warning, an immense wall of snow above rivers and dark forest. Clouds crossed its middle while the summit remained in another weather.": "デナリは低地から、ほとんど何の前触れもなく、川と暗い森の上に巨大な雪の壁をそびえ立ちます。雲が真ん中を横切っていたが、頂上は別の天気のままだった。",
