  "Dominican supporters' purse": "ドミニカ共和国サポーターの財布",
  "DON'T PET IT": "撫でない",
  "Double the watch by the precious metal. Greed swims farther than any pirate.": "貴金属を使用することで時計を 2 倍にします。貪欲はどんな海賊よりも遠くまで泳ぎます。",
  "DOUBLOONS SET TO 1,000,000": "ダブロンを 1,000,000 に設定",
