  "Duke of Burgundy {0}": "ブルゴーニュ公 {0}",
  "durable, visible trade goods for the upriver market": "上流市場向けの丈夫で目に見える貿易品",
  "Dust from the caravan road settles on the landing, where merchants weigh news from inland against news from the sea.": "商人たちはそこで商人たちが内陸からのニュースと海からのニュースを比較検討する踊り場に、キャラバンの道路からの砂埃が降り積もる。",
  "Dutch negotiated trade post": "オランダの交渉交易所",
  "Dutch settler colony": "オランダ人入植者の植民地",
  "DUTY {0}%": "関税{0}%",
  "Each day brings us nearer to {0} and the road to Mecca. I have waited years for the Hajj; I pray our passage remains safe.": "私たちは毎日{0}とメッカへの道に近づいています。私はハッジを何年も待ちました。私たちの通行が安全であることを祈ります。",
  "Eagle": "イーグル",
  "EARLIER ACCOUNTS": "以前のアカウント",
  "EARLIER DIVIDENDS": "前期の配当",
  "Earlier ledger activity ({0} entries)": "以前の台帳アクティビティ ({0} エントリ)",
  "EARLIER SHIP SALES": "初期の船舶販売",
  "EARLIER SHIPBUILDING COSTS": "初期の造船コスト",
  "Earlier shipyard accounts": "以前の造船所のアカウント",
  "Earlier Spanish footholds in Caracas failed. Losada proposes a new city, though Caracas and allied peoples have shown that a charter cannot secure the valley.": "カラカスにおけるスペインの初期の拠点は失敗に終わった。ロサダは新都市の建設を提案しているが、カラカスとその同盟国民は憲章では渓谷を確保できないことを示している。",
  "Earn 1,000,000 doubloons in a single voyage.": "1 回の航海で 1,000,000 ダブロンを獲得します。",
  "Earn 10,000 doubloons in one voyage.": "1 回の航海で 10,000 ダブロンを獲得します。",
  "Earn 100,000 doubloons in one voyage.": "1 回の航海で 100,000 ダブロンを獲得します。",
  "Eastern Mediterranean Combat Performance Benchmark": "東地中海戦闘パフォーマンスベンチマーク",
  "Eastern Orthodox": "東方正教",
  "Eastern Woodlands": "東部森林地帯",
  "Easy, captain. You found me out. Put the {0} away.": "簡単だよ、船長。あなたは私を見つけてくれました。 {0} を保管してください。",
  "Eat bamboo, avoid all work, and remain aboard": "竹を食べ、すべての仕事を避け、船に留まります",
  "Eat the fish, inspect the deck, and go wherever the ship goes": "魚を食べ、甲板を調べ、船が行くところならどこへでも行きましょう",
  "Eaton promises a commercial port and must arrive with something worth trading. Supply": "イートンは商業港を約束しており、取引に値する何かを持って到着する必要があります。供給",
  "Eats and drinks as much as one person while contributing nothing to shipboard work.": "船上での仕事には何も貢献せずに、一人分の量を食べたり飲んだりする。",
  "Eats as much as three people, drinks as much as one, and contributes nothing to shipboard work.": "3人分も食べ、1人分も飲むが、船上の仕事には何も貢献しない。",
  "Eats two fish rations each day and contributes nothing to shipboard work. If there is no fish aboard, he catches his own.": "毎日魚の配給量を 2 つ食べ、船上の仕事には何も貢献しません。船に魚がいない場合は、自分で魚を捕まえます。",
  "Echigo Nagao House": "越後長尾邸",
  "Echigo's governor and deputy may dispute authority. Neither disputes my seal.": "越後の知事と副官は権限を争う可能性がある。どちらも私の印章に異論はありません。",
  "Eeeh.": "えーっ。",
  "EFFECT": "効果",
  "effectDetail": "効果詳細",
  "Eight hundred people cannot live from a military chest. Add": "800人は軍用箱では生きていけない。追加",
  "El Dorado": "エルドラド",
  "El Dorado! The legendary city of gold is real.": "エルドラド！伝説の黄金都市は実在します。",
  "Elastic coconut-fibre rope stands up well to warm salt water.": "伸縮性のあるココナッツ繊維のロープは、温かい塩水にも十分耐えます。",
  "Elbrus carries two rounded summits beneath a single mantle of snow. It rises broad and pale above the Caucasus rather than cutting the sky like a narrow horn.": "エルブルスは、単一の雪のマントルの下に 2 つの丸い頂上を持っています。それは細い角のように空を切り裂くのではなく、コーカサス上空に広く青白くそびえ立っています。",
