  "Portuguese quarter": "ポルトガル地区",
  "Portuguese settler colony": "ポルトガル人入植者の植民地",
  "Portuguese sugar port": "ポルトガルの砂糖港",
  "Portuguese trading post": "ポルトガルの交易所",
  "Powder, provisions, and silence are all for sale. Cove specie: {0} db.": "火薬、食料、沈黙はすべて売り物です。入り江の種: {0} DB。",
  "Powerful yew bows reach farther across the water, but demand practiced archers.": "強力なイチイの弓は水を越えて遠くまで届きますが、熟練した射手が必要です。",
  "Powhatan": "ポウハタン",
  "Powhatan Confederacy": "ポウハタン連合",
  "Praise be to God, my Hajj is complete. Now I need passage home to {0}. Carry me there and I will pay {1} db.": "アッラーに感謝を。ハッジを終えました。今度は故郷の{0}まで船に乗せてください。送り届けてくだされば{1}ダブロンをお支払いします。",
  "Present arms and negotiate terms": "武器を提示して条件を交渉する",
