  "RIVAL DELEGATION DEFEATED - RETURN TO NINGBO": "ライバル代表団の敗北 - 寧波へ帰還",
  "River craft reach this far, but arrivals are uncommon enough that the market knows your cargo before the ropes are tied.": "川船はここまで到達しますが、到着するのは珍しいため、ロープが結ばれる前に市場が貨物を把握します。",
  "River craft, caravans, and sea-going merchants meet here, filling the customs house with a dozen languages.": "川船、キャラバン、航海商人がここに集まり、税関は十数か国語で埋め尽くされます。",
  "Roads and Inland Trade": "道路と内陸貿易",
  "Roanoke Clues": "ロアノークの手がかり",
  "ROANOKE CLUES ACQUIRED": "ロアノークの手がかりを入手",
  "Roanoke needs grain before another poor harvest turns trade into desperation.": "ロアノークには、再び不作が起きて貿易が絶望的になる前に穀物が必要だ。",
  "Roanoke remains silent. I have gathered all the clues this shore will yield; England must see them.": "ロアノークは沈黙を続ける。私はこの海岸で得られるすべての手がかりを集めました。イングランドは彼らを見る必要がある。",
  "ROANOKE REPORT DELIVERED +{0} DB": "ロアノーク レポートを配信 +{0} DB",
  "Roanoke? It is gone! We will search the shore and carry word to {0}.": "ロアノーク？ 消えている！ 岸を捜索し、{0}へ知らせを届けよう。",
