  "Santiago de Leon de Caracas now holds the valley, and the Indian name Caracas has already outlasted the one in the charter.": "現在この渓谷はサンティアゴ・デ・レオン・デ・カラカスが所有しており、インドの名前であるカラカスはすでに憲章にある名前よりも長く使われています。",
  "Sao Paulo de Luanda has become Portugal's fortified Angolan port. Its Atlantic wealth comes from inland war and the slave trade.": "サンパウロ デ ルアンダはポルトガルのアンゴラの要塞港となっています。大西洋の富は内陸戦争と奴隷貿易から来ています。",
  "Sao Sebastiao cannot secure Guanabara without more powder.": "サン・セバスティアンは、さらなる火薬がなければグアナバラを確保することはできない。",
  "Sao Sebastiao has secured Guanabara Bay for Portugal. Around the old redoubt, Rio de Janeiro is becoming a true port.": "サン・セバスティアンはポルトガルのグアナバラ湾を確保した。古い要塞の周囲で、リオデジャネイロは真の港になりつつあります。",
